    // 使用立即执行函数表达式(IIFE)来创建独立作用域，避免污染全局变量
    (function() {
        /* ==========================================================================
           初始化与辅助函数
           ========================================================================== */
        const parser = new DOMParser();
        const getData = (id) => document.getElementById(id)?.textContent || '';
        function escapeHtml(str) { const p = document.createElement('p'); p.textContent = str; return p.innerHTML; }
        function extractCdata(str) { const match = str.match(/<!\[CDATA\[([\s\S]*?)\]\]>/); return match ? match[1].trim() : str.trim(); }
        function getThemeClass(name) {
            switch (name) {
                case '顾盼兮': return 'gu-panxi-style';
                case '塞莱斯蒂娜': return 'celestine-style';
                case '用户': return 'user-status-style';
                default: return 'generic-style';
            }
        }

        /**
         * 处理选项点击事件，并发送消息到SillyTavern，同时触发AI回复。
         * 此函数被挂载到window对象上，以便HTML中的onclick属性可以调用。
         * @param {HTMLElement} clickedElement - 被点击的<li>元素。
         * @param {string} optionText - 选项的纯文本内容。
         */
        window.handleOptionClick = function(clickedElement, optionText) {
            if (typeof window.triggerSlash !== 'function') {
                console.error("SillyTavern API 'triggerSlash' not found.");
                alert("错误：无法连接到SillyTavern的发送功能。");
                return;
            }
            // 构造命令：发送用户选择，并用"|"分隔，附加"/trigger"命令以触发AI生成回复。
            const command = `/send {{user}} [选择] ${optionText}|/trigger`;
            console.log("正在发送命令到SillyTavern:", command);

            try {
                window.triggerSlash(command);
                const optionsList = document.getElementById('options-container');
                if (optionsList) {
                    optionsList.classList.add('disabled');
                    if(clickedElement) {
                        clickedElement.classList.add('selected-option');
                    }
                }
            } catch (error) {
                console.error("触发斜杠命令时出错:", error);
                alert("发送选项时出错: " + error.message);
            }
        }

        /* ==========================================================================
           各大模块渲染函数
           ========================================================================== */

        /**
         * 渲染主内容区域，并正确处理段落。
         * @param {string} rawData - 从捕获组1获取的XML字符串片段。
         */
        function renderMainContent(rawData) {
            const container = document.getElementById('main-content-container');
            if (!container || !rawData) return;
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            let finalHtml = '';
            doc.querySelector('root').childNodes.forEach(node => {
                if (node.nodeName === '面板' && node.textContent.trim()) {
                    finalHtml += extractCdata(node.textContent);
                } else if (node.nodeName === '文本' && node.textContent.trim()) {
                    const fullText = node.textContent;
                    const paragraphs = fullText.split(/\s*\n\s*/); // 按空白行分割段落
                    paragraphs.forEach(para => {
                        const trimmedPara = para.trim();
                        if (trimmedPara) { finalHtml += `<p>${escapeHtml(trimmedPara)}</p>`; }
                    });
                }
            });
            container.innerHTML = finalHtml;
        }

        /**
         * 动态渲染所有角色日志。
         * @param {string} rawData - 从捕获组2获取的XML字符串片段。
         */
        function renderLogs(rawData) {
            const container = document.getElementById('logs-container');
            if (!container || !rawData.trim()) { container.innerHTML = ''; return; }
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            const logCollection = doc.documentElement;
            if (!logCollection) { container.innerHTML = ''; return; }
            let finalHtml = '';
            Array.from(logCollection.children).forEach(logNode => {
                const tagName = logNode.tagName;
                if (!tagName || !tagName.startsWith('日志_')) return;
                const charName = tagName.split('_')[1];
                const icon = logNode.querySelector('日志图标')?.textContent || '📝';
                const logTitle = logNode.querySelector('日志标题')?.textContent || '日志';
                const logContentCdata = logNode.querySelector('日志内容')?.textContent || '';
                const logContent = escapeHtml(extractCdata(logContentCdata));
                const themeClass = getThemeClass(charName);
                finalHtml += `<details class='character-log-entry ${themeClass}' open><summary><span class="summary-icon">▼</span>${escapeHtml(icon)} ${escapeHtml(charName)}的${escapeHtml(logTitle)}</summary><div class='collapsible-content character-log'>${logContent}</div></details>`;
            });
            container.innerHTML = finalHtml;
        }

        /**
         * 渲染直播间模块。
         * @param {string} rawData - 从捕获组3获取的XML字符串片段。
         */
        function renderLiveRoom(rawData) {
            const container = document.getElementById('live-room-container');
            const summaryEl = document.getElementById('live-room-summary');
            if (!container || !summaryEl || !rawData) return;
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            const title = doc.querySelector('标题')?.textContent || '直播间';
            const viewers = doc.querySelector('人数')?.textContent || '0';
            const commentsHtml = Array.from(doc.querySelectorAll('评论')).map(c => `<div class='comment-item'>${escapeHtml(c.textContent)}</div>`).join('');
            summaryEl.innerHTML = `<span class="summary-icon">▼</span>🔞 ${escapeHtml(title)}`;
            container.innerHTML = `<div class='live-room-viewers'>👥 观看人数：<strong>${escapeHtml(viewers)}</strong> 人正在围观</div><div class='live-room-comments-container'>${commentsHtml}</div>`;
        }

        /**
         * 渲染抉择列表，并为每个选项添加点击事件。
         * @param {string} rawData - 从捕获组4获取的XML字符串片段。
         */
        function renderOptions(rawData) {
            const container = document.getElementById('options-container');
            if (!container) return;
            if (!rawData || !rawData.trim()) { container.innerHTML = ''; return; }
            container.classList.remove('disabled');
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            const optionNodes = doc.querySelectorAll('选项');
            if (optionNodes.length > 0) {
                const html = Array.from(optionNodes).map(node => {
                    const text = node.textContent.trim();
                    const escapedText = text.replace(/'/g, "\\'"); // 转义单引号以用于onclick属性
                    let displayText = '';
                    const match = text.match(/^(\[.*?\])(.*)/);
                    if (match) {
                        displayText = `<span class="option-prefix">${escapeHtml(match[1])}</span>${escapeHtml(match[2].trim())}`;
                    } else {
                        displayText = escapeHtml(text);
                    }
                    return `<li onclick="window.handleOptionClick(this, '${escapedText}')">${displayText}</li>`;
                }).join('');
                container.innerHTML = html;
            } else {
                container.innerHTML = '';
            }
        }

        /**
         * [辅助] 为单个状态模块生成其内部的HTML内容。
         * @param {Element} statusNode - 单个角色的状态XML节点。
         * @returns {string} 生成的HTML字符串。
         */
        function generateStatusContentHtml(statusNode) {
            if (!statusNode) return '';
            let contentHtml = '';
            statusNode.querySelectorAll('条目').forEach(item => {
                const key = item.getAttribute('键');
                const value = item.getAttribute('值');
                if (key) contentHtml += `<p><strong>${escapeHtml(key)}:</strong> ${escapeHtml(value)}</p>`;
            });
            statusNode.querySelectorAll('计量条').forEach(meter => {
                const label = meter.getAttribute('标签');
                const value = meter.getAttribute('值') || '0';
                const max = meter.getAttribute('最大值') || '100';
                const suffix = meter.getAttribute('文本后缀') || '';
                if (label) contentHtml += `<div class="meter-row"><div class="status-label"><strong>${escapeHtml(label)}:</strong> ${value}/${max} ${escapeHtml(suffix)}</div><meter value='${value}' min='0' max='${max}'></meter></div>`;
            });
            return contentHtml;
        }

        /**
         * 动态渲染所有角色状态栏。
         * @param {string} rawData - 从捕获组5获取的XML字符串片段。
         */
        function renderStatusBars(rawData) {
            const container = document.getElementById('status-bars-container');
            if (!container || !rawData.trim()) { container.innerHTML = ''; return; }
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            const statusCollection = doc.documentElement;
            if (!statusCollection) { container.innerHTML = ''; return; }
            let finalHtml = '';
            Array.from(statusCollection.children).forEach(statusNode => {
                const tagName = statusNode.tagName;
                if (!tagName || !tagName.startsWith('状态_')) return;
                const charName = tagName.split('_')[1];
                const icon = statusNode.querySelector('状态图标')?.textContent || '📊';
                const summaryTitle = (charName === '用户') ? '我的状态' : `${charName}的状态`;
                const themeClass = getThemeClass(charName);
                const contentHtml = generateStatusContentHtml(statusNode);
                if (contentHtml) {
                    finalHtml += `<details class='status-bar-entry ${themeClass}' open><summary><span class="summary-icon">▼</span>${escapeHtml(icon)} ${escapeHtml(summaryTitle)}</summary><div class='collapsible-content status-bar-module'>${contentHtml}</div></details>`;
                }
            });
            container.innerHTML = finalHtml;
        }

        /* ==========================================================================
           主执行函数
           ========================================================================== */

        /**
         * 主函数，负责按顺序调用所有渲染函数。
         */
        function main() {
            renderMainContent(getData('data-group-1'));
            renderLogs(getData('data-group-2'));
            renderLiveRoom(getData('data-group-3'));
            renderOptions(getData('data-group-4'));
            renderStatusBars(getData('data-group-5'));
        }

        // 确保在DOM加载完成后再执行脚本
        if (document.readyState === 'loading') { 
            document.addEventListener('DOMContentLoaded', main); 
        } else { 
            main(); 
        }
    })();
    </script>
