    // 使用立即执行函数表达式(IIFE)来创建独立作用域，避免污染全局变量
    (function() {
        /* ==========================================================================
           初始化与辅助函数
           ========================================================================== */
        const parser = new DOMParser();
        const getData = (id) => document.getElementById(id)?.textContent || '';
        function escapeHtml(str) { const p = document.createElement('p'); p.textContent = str; return p.innerHTML; }
        function extractCdata(str) { const match = str.match(/<!\[CDATA\[([\s\S]*?)\]\]>/); return match ? match[1].trim() : str.trim(); }
        function getThemeClass(name) {
            switch (name) {
                case '顾盼兮': return 'gu-panxi-style';
                case '塞莱斯蒂娜': return 'celestine-style';
                case '用户': return 'user-status-style';
