        /**
         * 渲染主内容区域，并正确处理段落。
         * @param {string} rawData - 从捕获组1获取的XML字符串片段。
         */
        function renderMainContent(rawData) {
            const container = document.getElementById('main-content-container');
            if (!container || !rawData) return;
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            let finalHtml = '';
            doc.querySelector('root').childNodes.forEach(node => {
                if (node.nodeName === '面板' && node.textContent.trim()) {
                    finalHtml += extractCdata(node.textContent);
                } else if (node.nodeName === '文本' && node.textContent.trim()) {
                    const fullText = node.textContent;
                    const paragraphs = fullText.split(/\s*\n\s*/); // 按空白行分割段落
                    paragraphs.forEach(para => {
                        const trimmedPara = para.trim();
                        if (trimmedPara) { finalHtml += `<p>${escapeHtml(trimmedPara)}</p>`; }
                    });
                }
            });
            container.innerHTML = finalHtml;
        }

        /**
         * 动态渲染所有角色日志。
         * @param {string} rawData - 从捕获组2获取的XML字符串片段。
         */
        function renderLogs(rawData) {
            const container = document.getElementById('logs-container');
            if (!container || !rawData.trim()) { container.innerHTML = ''; return; }
            const doc = parser.parseFromString(`<root>${rawData}</root>`, "text/xml");
            const logCollection = doc.documentElement;
            if (!logCollection) { container.innerHTML = ''; return; }
            let finalHtml = '';
            Array.from(logCollection.children).forEach(logNode => {
                const tagName = logNode.tagName;
                if (!tagName || !tagName.startsWith('日志_')) return;
                const charName = tagName.split('_')[1];
                const icon = logNode.querySelector('日志图标')?.textContent || '📝';
                const logTitle = logNode.querySelector('日志标题')?.textContent || '日志';
                const logContentCdata = logNode.querySelector('日志内容')?.textContent || '';
                const logContent = escapeHtml(extractCdata(logContentCdata));
                const themeClass = getThemeClass(charName);
                finalHtml += `<details class='character-log-entry ${themeClass}' open><summary><span class="summary-icon">▼</span>${escapeHtml(icon)} ${escapeHtml(charName)}的${escapeHtml(logTitle)}</summary><div class='collapsible-content character-log'>${logContent}</div></details>`;
            });
            container.innerHTML = finalHtml;
        }

