    <!-- 1. 原始数据容器 (隐藏): 使用 $1 来接收完整的、可能包含多行的文本 -->
    <div id="raw-input-data" style="display:none;">$1</div>

    <!-- 2. 输出容器: JS将把最终的美化HTML渲染到这里 -->
    <div id="output-container"></div>

    <script>
        // 使用IIFE创建独立作用域
        (function() {
            // 安全转义HTML的辅助函数
            function escapeHtml(str) {
                const p = document.createElement('p');
                p.textContent = str;
                return p.innerHTML;
            }

            // 获取原始输入文本。注意：这里不再使用.trim()，以保留用户可能输入的纯空格或换行
            const rawInput = document.getElementById('raw-input-data').textContent;
            const outputContainer = document.getElementById('output-container');

            // 定义用于判断是否为脚本输入的正则表达式
            const scriptInputRegex = /^(\【.*?】\s*\[选择\]\s*\[.*?\])([\s\S]*)$/; // 使用[\s\S]*以匹配多行内容

            let finalHtml = '';

            // 3. 核心逻辑判断
            const scriptMatch = rawInput.match(scriptInputRegex);

            if (scriptMatch) {
                // 情况一: 匹配成功，这是由UI脚本生成的“选择”消息
                const prefix = scriptMatch[1];
                const content = scriptMatch[2];

                finalHtml = `
                    <div class="styled-input-wrapper">
                        <div class="styled-input-base script-input-style">
                            <span class="prefix">${escapeHtml(prefix)}</span>
                            <span>${escapeHtml(content)}</span>
                        </div>
                    </div>
                `;
            } else {
                // 情况二: 匹配失败，这是用户手动输入的消息
                let contentToDisplay = rawInput;
                let extraClass = '';

                if (rawInput.startsWith('*') && rawInput.endsWith('*')) {
                    contentToDisplay = rawInput.slice(1, -1);
                    extraClass = 'is-narrator';
                }

                finalHtml = `
                    <div class="styled-input-wrapper">
                        <div class="styled-input-base manual-input-style ${extraClass}">
                            <span>${escapeHtml(contentToDisplay)}</span>
                        </div>
                    </div>
                `;
            }

            // 4. 将生成好的HTML注入到输出容器中
            outputContainer.innerHTML = finalHtml;
        })();
    </script>
</body>
</html>



